#!/usr/bin/env bash
# Phase 4 launches. Every run is resumable and skipped when finished, so a launch can simply be repeated.
# Usage (from the repo root): bash scripts/run_phase4.sh <launch> [python]
# Do not edit this file while a launch is running (bash reads it as it goes).
set -euo pipefail

main() {
  local what=$1 PY=${2:-python}
  export PYTHONPATH=src
  case "$what" in
    data)      $PY -m phase4.generate && $PY -m phase4.analysis data ;;
    # 4.1 size check: 20 minutes each, one after the other so that neither slows the other
    size)      for s in small medium; do
                 $PY -m phase4.train --name "size_$s" --size "$s" --max-minutes 20 --no-plateau; done ;;
    size-large) $PY -m phase4.train --name size_large --size large --max-minutes 20 --no-plateau ;;
    # 4.1 training to the plateau; one launch stays under 2 hours and the next one resumes
    sft)       $PY -m phase4.train --name sft --size "${SIZE:?set SIZE=small|medium|large}" --launch-minutes 110 ;;
    sft-report) $PY -m phase4.analysis sft --size "${SIZE:-medium}" ;;
    sampler)   $PY -m phase4.sampler_eval --size "${SIZE:-medium}" ;;   # 4.2, about 11 minutes
    # 4.4: the seven phase 3 objectives from the plateau model, hard band, 4 sampler steps. One seed per launch
    # (SEED=0|1|2, about 7 minutes per run alone); the three seeds can run side by side.
    rl44)      local R="$PY -m phase3.rl --config configs/phase4_rl.yaml --exp 4.4 --seed ${SEED:?set SEED}"
               $R
               $R --set rl.objective_params.beta=0
               $R --set rl.objective_params.floor=-75.6
               $R --set rl.ref_kl=0.01
               $R --set rl.objective=filtered
               $R --set rl.objective=self_diffusion
               $R --set rl.objective=grpo ;;
    # 4.4 horizon check: one wd1 run of 1,000 steps
    rl44-h)    $PY -m phase3.rl --config configs/phase4_rl.yaml --exp 4.4 --seed 0 --tag _h1000 --set rl.max_rl_steps=1000 ;;
    # 4.5a factorial on floored wd1: order (fixed / sampled, tau_o 0.05) x weights (group / batch).
    # The fixed-order, group cell is the floored arm of 4.4. One launch per arm (three seeds in parallel).
    rl45a-ord|rl45a-batch|rl45a-both)
               local R="$PY -m phase3.rl --config configs/phase4_rl.yaml --exp 4.5a --seed ${SEED:?set SEED} --set rl.objective_params.floor=-75.6"
               case "$what" in
                 rl45a-ord)   $R rl.order_temp=0.05 ;;
                 rl45a-batch) $R rl.weights_over=batch ;;
                 rl45a-both)  $R rl.order_temp=0.05 rl.weights_over=batch ;;
               esac ;;
    # 4.6c regime map for the push-down term (docs/RL_DLLM_DIRECTIONS.md, direction 2), one launch per arm,
    # three seeds side by side. r1-r3: one change each against 4.4 / 4.5a. r4-r5: dense reward (uses labels).
    # r6-r8: 2 sampler steps in rollouts and evaluation.
    rl46-r1|rl46-r2|rl46-r3|rl46-r4|rl46-r5|rl46-r6|rl46-r7|rl46-r8)
               local R="$PY -m phase3.rl --config configs/phase4_rl.yaml --exp 4.6c --seed ${SEED:?set SEED}"
               case "$what" in
                 rl46-r1) $R --set rl.weights_over=batch rl.objective_params.beta=0 ;;
                 rl46-r2) $R --tag _mu1 --set rl.inner_steps=1 ;;
                 rl46-r3) $R --tag _paperopt --set rl.lr=3e-6 rl.grad_clip=0.2 rl.weight_decay=0.1 ;;
                 rl46-r4) $R --set rl.reward=cell_accuracy ;;
                 rl46-r5) $R --set rl.reward=cell_accuracy rl.objective_params.beta=0 ;;
                 rl46-r6) $R --tag _s2 --set rl.rollout_steps=2 ;;
                 rl46-r7) $R --tag _s2 --set rl.rollout_steps=2 rl.objective_params.beta=0 ;;
                 rl46-r8) $R --tag _s2 --set rl.rollout_steps=2 rl.objective=filtered ;;
               esac ;;
    # 4.6d what self-training learns (direction 4): the supervised objective on all puzzles / on solved ones
    rl46-sup-all|rl46-sup-solved|rl46-sup-unsolved)
               $PY -m phase3.rl --config configs/phase4_rl.yaml --exp 4.6d --seed "${SEED:?set SEED}" \
                 --set rl.objective=supervised "rl.supervised_on=${what#rl46-sup-}" ;;
    # 4.8a cold start with no stored solutions (docs/SELF_LEARNING_FROM_CHECKER.md, stage A1): 60 min on masked givens
    self-a1)   $PY -m phase4.train --name a1 --size medium --loss givens --max-minutes 60 --no-plateau \
                 --out results/phase4/4.8a --ckpt-dir ~/dllm-cache/phase4/4.8a/a1
               $PY -m phase4.selflearn --name a1 ;;
    # 4.8b self-training from the rule checker (stage A2), from the 4.8a model. ARM=givens|harvest|hindsight, one arm
    # at a time; a launch pauses after 100 minutes at the next round end, repeat it until it prints "finished".
    self-a2)   $PY -m phase4.selfloop --arm "${ARM:?set ARM}" --launch-minutes 100
               if [ -f "results/phase4/4.8b/$ARM.json" ]; then $PY -m phase4.selflearn --exp 4.8b --name "$ARM"; fi ;;
    # 4.8c seeds 1 and 2 of the harvest and hindsight arms of 4.8b (same start model). ARM=harvest|hindsight SEED=1|2.
    self-a2-seed) n="${ARM:?set ARM}_s${SEED:?set SEED}"
               $PY -m phase4.selfloop --arm "$ARM" --exp 4.8c --name "$n" --launch-minutes 100 --set diffusion_training.seed="$SEED"
               if [ -f "results/phase4/4.8c/$n.json" ]; then $PY -m phase4.selflearn --exp 4.8c --name "$n"; fi ;;
    # 4.8d the seed-0 hindsight run of 4.8b continued to 34 rounds (step 43,546, the step of the supervised plateau).
    # The first launch copies the 4.8b state (model, optimiser, buffer, rng) and its per-round log, then resumes.
    self-a2-long) c="$HOME/dllm-cache/phase4"; mkdir -p "$c/4.8d/hindsight_long" results/phase4/4.8d
               [ -f "$c/4.8d/hindsight_long/state.pt" ] || { cp "$c/4.8b/hindsight/state.pt" "$c/4.8d/hindsight_long/state.pt"
                 cp results/phase4/4.8b/hindsight.csv results/phase4/4.8d/hindsight_long.csv; }
               $PY -m phase4.selfloop --arm hindsight --exp 4.8d --name hindsight_long --rounds 34 --launch-minutes 100
               if [ -f results/phase4/4.8d/hindsight_long.json ]; then $PY -m phase4.selflearn --exp 4.8d --name hindsight_long; fi ;;
    self-a2-ctrl-long) c="$HOME/dllm-cache/phase4"; mkdir -p "$c/4.8e/givens_long" results/phase4/4.8e
               [ -f "$c/4.8e/givens_long/state.pt" ] || { cp "$c/4.8b/givens/state.pt" "$c/4.8e/givens_long/state.pt"
                 cp results/phase4/4.8b/givens.csv results/phase4/4.8e/givens_long.csv; }
               $PY -m phase4.selfloop --arm givens --exp 4.8e --name givens_long --rounds 34 --launch-minutes 100
               if [ -f results/phase4/4.8e/givens_long.json ]; then $PY -m phase4.selflearn --exp 4.8e --name givens_long; fi ;;
    givens-probe) $PY -m phase4.givens_probe ;;
    # 4.9b low-lr training of the givens-only model (4.8e) on its own valid grids; one launch per arm, three seeds
    # side by side. self4: rollouts with 4 sampler steps (as 4.4); self16: with 16; ctrl: givens loss, checker unused.
    self49-self4|self49-self16|self49-ctrl)
               local R="$PY -m phase3.rl --config configs/phase4_rl_givens.yaml --exp 4.9b --seed ${SEED:?set SEED}"
               case "$what" in
                 self49-self4)  $R ;;
                 self49-self16) $R --set rl.harvest_steps=16 ;;
                 self49-ctrl)   $R --set rl.objective=givens ;;
               esac ;;
    # 4.9c which difference from the long hindsight loop matters: the self4 arm of 4.9b at the loop's learning rate
    # (3e-4) and at 1e-4, and unchanged from the hindsight_long model of 4.8d. Three seeds side by side per launch.
    self49c-lr3e-4|self49c-lr1e-4|self49c-hind)
               local R="$PY -m phase3.rl --config configs/phase4_rl_givens.yaml --exp 4.9c --seed ${SEED:?set SEED}"
               case "$what" in
                 self49c-hind) $R --tag _hind --init "$HOME/dllm-cache/phase4/4.8d/hindsight_long/final.pt" ;;
                 *)            $R --tag "_${what#self49c-}" --set "rl.lr=${what#self49c-lr}" ;;
               esac ;;
    # 4.9d the two long runs continued for 4 rounds with their own all-band training, learning rate 1e-5 instead of 3e-4
    self49d-hind|self49d-givens)
               local c="$HOME/dllm-cache/phase4" arm src n
               case "$what" in
                 self49d-hind)   arm=hindsight; src=4.8d/hindsight_long ;;
                 self49d-givens) arm=givens;    src=4.8e/givens_long ;;
               esac
               n="${arm}_lr1e-5"; mkdir -p "$c/4.9d/$n" results/phase4/4.9d
               [ -f "$c/4.9d/$n/state.pt" ] || { cp "$c/$src/state.pt" "$c/4.9d/$n/state.pt"
                 cp "results/phase4/$src.csv" "results/phase4/4.9d/$n.csv"; }
               $PY -m phase4.selfloop --arm $arm --exp 4.9d --name $n --rounds 38 --lr 1e-5 --launch-minutes 100
               if [ -f "results/phase4/4.9d/$n.json" ]; then
                 $PY -m phase4.selflearn --exp 4.9d --name $n --split val
                 $PY -m phase4.selflearn --exp 4.9d --name $n --split test
               fi ;;
    # 4.9e the supervised model of 4.1 continued for 4,000 steps at learning rate 1e-5 (the reference for 4.9d)
    self49e-sft) local c="$HOME/dllm-cache/phase4/4.9e/sft_lr1e-5"; mkdir -p "$c" results/phase4/4.9e
               [ -f "$c/state.pt" ] || { cp "$HOME/dllm-cache/phase4/sft/sft/state.pt" "$c/state.pt"
                 cp results/phase4/sft/sft.csv results/phase4/4.9e/sft_lr1e-5.csv; }
               $PY -m phase4.train --name sft_lr1e-5 --size medium --out results/phase4/4.9e --ckpt-dir "$c" \
                   --no-plateau --max-steps 47500 --lr 1e-5 --launch-minutes 100
               if [ -f results/phase4/4.9e/sft_lr1e-5.json ]; then
                 $PY -m phase4.selflearn --exp 4.9e --name sft_lr1e-5 --split val
                 $PY -m phase4.selflearn --exp 4.9e --name sft_lr1e-5 --split test
               fi ;;
    # 4.9f the 4.4 self-training step from the supervised model after its lr drop (4.9e); sup: same steps on stored solutions
    self49f-self|self49f-sup)
               local R="$PY -m phase3.rl --config configs/phase4_rl_sftlr.yaml --exp 4.9f --seed ${SEED:?set SEED}"
               case "$what" in
                 self49f-self) $R ;;
                 self49f-sup)  $R --set rl.objective=supervised ;;
               esac ;;
    *) echo "unknown launch: $what" >&2; exit 1 ;;
  esac
}
main "$@"
